.fsx-ways{--navy: #26275B; --navy-deep: #1D1E4A; --blue: #4E98D8; --blue-ink: #2F78BA; --teal: #7CD2D3; --mid: #528FC0; --royal: #2E4DA5; --ink: #221C1B; --body: #3A3650; --muted: #6A6880; --bg: #F8F7F7; --white: #FFFFFF; --line: #E3E2EA; --star: #F4B400; --ph: #FFE45C; --grad: linear-gradient(90deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --grad-diag: linear-gradient(120deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --font: "Poppins", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --font-ui: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --content: 1240px; --pad-x: 24px; --shadow-card: 0 18px 40px -18px rgba(38, 39, 91, .28); --shadow-btn: 0 14px 30px -12px rgba(46, 77, 165, .55); --navy: #250762; --navy-deep: #1A0446; --blue: #3299D5; --blue-ink: #1F78B4; --ink: #1C1B22; --body: #2F2E36; --muted: #6B6A72; --tint: #EEF0F9; --aqua: #72CCD8; --royal: #174FA2; --grey: #D9D8D7; --teal: #72CCD8; --mid: #3299D5; --grad: linear-gradient(90deg, #72CCD8 0%, #174FA2 100%); --grad-diag: linear-gradient(120deg, #72CCD8 0%, #174FA2 100%); --grad-text: linear-gradient(90deg, #72CCD8 0%, #3299D5 45%, #174FA2 100%); --grad-primary: linear-gradient(135deg, #2B0A80 0%, #250762 55%, #200556 100%); --grad-icon: linear-gradient(135deg, #3299D5 0%, #250762 100%); --shadow-btn: 0 14px 30px -12px rgba(37, 7, 98, .55); font-family:Poppins, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;font-size:18px;line-height:28.8px;color:rgb(28, 27, 34); display:block;} .fsx-ways *, .fsx-ways *::before, .fsx-ways *::after{box-sizing:border-box;}
.fsx-ways button{background:none;border:0;padding:0;margin:0;font:inherit;color:inherit;border-radius:0;text-transform:none;letter-spacing:inherit;box-shadow:none;cursor:pointer;}
.fsx-ways button:hover, .fsx-ways button:focus{background:none;color:inherit;}
.fsx-ways a{color:inherit;text-decoration:none;background:none;} .fsx-ways a:hover{color:inherit;}
.fsx-ways h1, .fsx-ways h2, .fsx-ways h3, .fsx-ways h4, .fsx-ways p, .fsx-ways ul, .fsx-ways ol, .fsx-ways figure{margin:0;padding:0;} .fsx-ways ul, .fsx-ways ol{list-style:none;}
.fsx-ways img, .fsx-ways svg{display:block;max-width:100%;height:auto;}
.fsx-ways { --navy: #26275B;
  --navy-deep: #1D1E4A;
  --blue: #4E98D8;
  --blue-ink: #2F78BA;   
  --teal: #7CD2D3;
  --mid: #528FC0;
  --royal: #2E4DA5;
  --ink: #221C1B;
  --body: #3A3650;
  --muted: #6A6880;
  --bg: #F8F7F7;
  --white: #FFFFFF;
  --line: #E3E2EA;
  --star: #F4B400;
  --ph: #FFE45C;

  --grad: linear-gradient(90deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%);
  --grad-diag: linear-gradient(120deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%);

  --font: "Poppins", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  --font-ui: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;

  --content: 1240px;
  --pad-x: 24px;
  --shadow-card: 0 18px 40px -18px rgba(38, 39, 91, .28);
  --shadow-btn: 0 14px 30px -12px rgba(46, 77, 165, .55); }
.fsx-ways *, .fsx-ways *::before, .fsx-ways *::after { box-sizing: border-box; }
.fsx-ways { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
.fsx-ways { margin: 0; font-family: var(--font); font-size: 18px; line-height: 1.6; color: var(--ink); background: var(--bg); -webkit-font-smoothing: antialiased; }
.fsx-ways img, .fsx-ways svg { display: block; max-width: 100%; }
.fsx-ways img { height: auto; }
.fsx-ways h2, .fsx-ways h3, .fsx-ways h4 { margin: 0; font-family: var(--font); color: var(--navy); line-height: 1.1; letter-spacing: -0.015em; }
.fsx-ways p { margin: 0 0 1em; }
.fsx-ways p:last-child { margin-bottom: 0; }
.fsx-ways ul { margin: 0; padding: 0; list-style: none; }
.fsx-ways a { color: inherit; }
.fsx-ways button { font: inherit; color: inherit; }
.fsx-ways .icon { width: 24px; height: 24px; flex: none; }
.fsx-ways .fsx-con { width: 100%; max-width: calc(var(--content) + var(--pad-x) * 2); margin-inline: auto; padding-inline: var(--pad-x); }
.fsx-ways .bg-geo { background: var(--bg) url("https://cdn.jsdelivr.net/gh/chrismitchell-cmd/first-search-marketing@4d59b7976a0bacac8601ce9d2eba36ebb43a7779/elementor/upload/first-search/design/bg-geometric.jpg") center / cover no-repeat; }
.fsx-ways .eyebrow { display: block; margin-bottom: 14px; font-weight: 600; font-size: 17px; color: var(--blue-ink); letter-spacing: 0; }
.fsx-ways .h2 { font-weight: 700; font-size: clamp(34px, 3.9vw, 56px); line-height: 1.08; }
.fsx-ways .btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  padding: 14px 28px; border: 0; border-radius: 10px; cursor: pointer;
  font-family: var(--font); font-weight: 500; font-size: 20px; line-height: 1.2; text-decoration: none; text-align: center;
  color: var(--white); background: var(--grad); background-size: 140% 100%; background-position: 0% 0;
  box-shadow: var(--shadow-btn); text-shadow: 0 1px 2px rgba(20, 30, 80, .35);
  transition: background-position .35s ease, transform .2s ease, box-shadow .2s ease; }
.fsx-ways .btn:hover { background-position: 100% 0; transform: translateY(-2px); box-shadow: 0 18px 34px -12px rgba(46, 77, 165, .65); }
.fsx-ways .link-u { font-weight: 500; font-style: italic; font-size: 20px; color: var(--navy);
  text-decoration: underline; text-decoration-color: var(--teal); text-decoration-thickness: 3px; text-underline-offset: 6px;
  background: none; border: 0; padding: 0; cursor: pointer; }
.fsx-ways .link-u:hover { color: var(--royal); text-decoration-color: var(--royal); }
.fsx-ways .gcard { --bw: 8px; --r: 40px; padding: var(--bw); border-radius: var(--r); background: var(--grad-diag); box-shadow: var(--shadow-card); }
.fsx-ways .gcard__in { height: 100%; background: var(--white); border-radius: calc(var(--r) - var(--bw)); }
.fsx-ways .ph { border-radius: 3px; transition: background-color .2s ease, box-shadow .2s ease; }
.fsx-ways .spots-bar { display: grid; grid-template-columns: repeat(25, 1fr); gap: 4px; margin-bottom: 10px; }
.fsx-ways .spots-bar span { height: 10px; border-radius: 3px; background: rgba(255, 255, 255, .14); }
.fsx-ways .spots-bar span.on { background: #8BCBEF; }
.fsx-ways .spots-label { font-size: 14px; font-weight: 600; margin-bottom: 24px; }
.fsx-ways .diy-logos { display: flex; flex-wrap: wrap; align-items: center; gap: 24px 56px; margin: -8px 0 26px 20px; }
.fsx-ways .diy-logos img { height: 78px; width: auto; }
@media (max-width: 767px) { .fsx-ways { --pad-x: 16px; } }
@media (max-width: 767px) { .fsx-ways { font-size: 16.5px; } }
@media (max-width: 767px) { .fsx-ways .diy-logos { margin-left: 0; gap: 18px 28px; } }
@media (max-width: 767px) { .fsx-ways .diy-logos img { height: 54px; } }
@media (prefers-reduced-motion: reduce) { .fsx-ways { scroll-behavior: auto; } }
@media (prefers-reduced-motion: reduce) { .fsx-ways *, .fsx-ways *::before, .fsx-ways *::after { transition-duration: .01ms !important; animation: none !important; } }
.fsx-ways { --navy: #250762;            
  --navy-deep: #1A0446;
  --blue: #3299D5;            
  --blue-ink: #1F78B4;        
  --ink: #1C1B22;             
  --body: #2F2E36;
  --muted: #6B6A72;
  --tint: #EEF0F9;            
  --aqua: #72CCD8; --royal: #174FA2; --grey: #D9D8D7; --teal: #72CCD8; --mid: #3299D5;
  --grad: linear-gradient(90deg, #72CCD8 0%, #174FA2 100%);          
  --grad-diag: linear-gradient(120deg, #72CCD8 0%, #174FA2 100%);
  --grad-text: linear-gradient(90deg, #72CCD8 0%, #3299D5 45%, #174FA2 100%);
  --grad-primary: linear-gradient(135deg, #2B0A80 0%, #250762 55%, #200556 100%);
  --grad-icon: linear-gradient(135deg, #3299D5 0%, #250762 100%);
  --shadow-btn: 0 14px 30px -12px rgba(37, 7, 98, .55); }
.fsx-ways h2, .fsx-ways h3, .fsx-ways h4 { color: var(--navy); }
.fsx-ways .lead { color: var(--body); }
.fsx-ways .eyebrow { color: var(--blue-ink); font-weight: 600; letter-spacing: .01em; }
.fsx-ways .link-u { color: var(--navy); text-decoration-color: var(--blue); }
.fsx-ways .btn { border-radius: 10px; font-weight: 600; font-size: 18px; letter-spacing: .005em; color: var(--white); background: var(--grad-primary); background-size: 100% 100%; text-shadow: none; border: 2px solid #4AA6DC; box-shadow: 0 0 0 1px rgba(114, 204, 216, .35), 0 10px 22px -8px rgba(50, 153, 213, .55); }
.fsx-ways .btn:hover { color: var(--white); background: linear-gradient(135deg, #300C8C 0%, #2A0874 100%); box-shadow: 0 0 0 3px rgba(114, 204, 216, .35), 0 14px 28px -8px rgba(50, 153, 213, .65); }
.fsx-ways .vid { --bw: 6px; --r: 48px; position: relative; width: 100%; align-self: center; }
.fsx-ways .vid .gcard__in { overflow: hidden; padding: 0; }
.fsx-ways .vid-btn { position: relative; display: block; width: 100%; aspect-ratio: 16 / 11; padding: 0; border: 0; cursor: pointer; overflow: hidden;
  background: radial-gradient(70% 60% at 50% 105%, rgba(50, 153, 213, .9), transparent 70%), radial-gradient(60% 50% at 0% 0%, rgba(124, 210, 211, .35), transparent 70%), var(--navy); }
.fsx-ways .vid-btn img { position: absolute; left: 50%; bottom: 0; height: 92%; width: auto; max-width: none; transform: translateX(-50%); object-fit: contain; }
.fsx-ways .vid-btn img.cover { left: 0; top: 0; width: 100%; height: 100%; transform: none; object-fit: cover; opacity: .55; }
.fsx-ways .vid-btn img.wide { left: 3%; width: 94%; height: auto; transform: none; }
.fsx-ways .vid-play { position: absolute; left: 50%; top: 50%; width: 92px; height: 92px; margin: -46px 0 0 -46px; border-radius: 50%; display: grid; place-items: center; background: rgba(255, 255, 255, .95); color: var(--navy); box-shadow: 0 0 0 12px rgba(255, 255, 255, .22), 0 20px 40px -12px rgba(16, 12, 48, .7); transition: transform .2s ease, box-shadow .2s ease; }
.fsx-ways .vid-play svg { width: 34px; height: 34px; margin-left: 5px; }
.fsx-ways .vid-btn:hover .vid-play { transform: scale(1.06); box-shadow: 0 0 0 18px rgba(255, 255, 255, .25), 0 20px 40px -12px rgba(16, 12, 48, .7); }
.fsx-ways .vid-cap { position: absolute; left: 20px; right: 20px; bottom: 18px; display: flex; justify-content: space-between; align-items: center; gap: 12px; text-align: left; }
.fsx-ways .vid-cap b { padding: 9px 14px; border-radius: 14px; background: rgba(255, 255, 255, .95); font-family: var(--font); font-weight: 600; font-size: 15px; color: var(--navy); line-height: 1.25; }
.fsx-ways .vid-cap span { flex: none; padding: 6px 10px; border-radius: 999px; background: rgba(16, 12, 48, .7); font-family: var(--font-ui); font-size: 13px; color: var(--white); }
.fsx-ways .vid-tag { position: absolute; left: 22px; top: 20px; display: inline-flex; align-items: center; gap: 8px; padding: 7px 13px; border-radius: 999px; background: rgba(255, 255, 255, .14); border: 1px solid rgba(255, 255, 255, .3); font-family: var(--font-ui); font-size: 13px; font-weight: 600; color: var(--white); }
.fsx-ways .vid-tag i { width: 8px; height: 8px; border-radius: 50%; background: #FF5A5A; box-shadow: 0 0 0 4px rgba(255, 90, 90, .25); }
.fsx-ways .vid-btn.is-playing .vid-play { display: none; }
.fsx-ways .vid-btn.is-playing::after { content: "Video plays here (placeholder)"; position: absolute; inset: 0; display: grid; place-items: center; background: rgba(16, 12, 48, .78); color: var(--white); font: 600 18px var(--font); }
@media (max-width: 767px) { .fsx-ways .vid { --bw: 5px; --r: 34px; } }
@media (max-width: 767px) { .fsx-ways .vid-play { width: 72px; height: 72px; margin: -36px 0 0 -36px; } }
@media (max-width: 767px) { .fsx-ways .vid-cap b { font-size: 13.5px; } }
.fsx-ways .ways2 { padding-block: clamp(110px, 11vw, 160px) clamp(80px, 9vw, 120px); }
.fsx-ways .ways2-head { max-width: 860px; margin-bottom: 34px; }
.fsx-ways .ways2-head .lead { margin-top: 14px; font-size: clamp(17px, 1.6vw, 21px); }
.fsx-ways .wt-tabs { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 30px; padding: 8px; border-radius: 30px; background: var(--white); box-shadow: var(--shadow-card); }
.fsx-ways .wt-tabs button { display: flex; align-items: center; gap: 16px; padding: 16px 20px; border: 0; border-radius: 22px; background: transparent; text-align: left; cursor: pointer; font-family: var(--font); color: var(--navy); transition: background .2s ease, color .2s ease; }
.fsx-ways .wt-tabs button:hover { background: var(--tint); }
.fsx-ways .wt-tabs i { width: 46px; height: 46px; flex: none; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-weight: 800; font-size: 20px; background: var(--tint); color: var(--navy); }
.fsx-ways .wt-tabs b { display: block; font-size: clamp(18px, 1.7vw, 22px); font-weight: 700; line-height: 1.2; }
.fsx-ways .wt-tabs small { display: block; margin-top: 2px; font-family: var(--font-ui); font-size: 14px; color: var(--muted); }
.fsx-ways .wt-tabs [aria-selected="true"], .fsx-ways .wt-tabs [aria-selected="true"]:hover { background: var(--navy); color: var(--white); }
.fsx-ways .wt-tabs [aria-selected="true"] i { background: var(--grad-diag); color: var(--white); }
.fsx-ways .wt-tabs [aria-selected="true"] small { color: rgba(255, 255, 255, .8); }
.fsx-ways .wt-panel { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.12fr); gap: 28px; align-items: stretch; }
.fsx-ways .wt-panel[hidden] { display: none; }
.fsx-ways .wt-card { --bw: 8px; --r: 44px; }
.fsx-ways .wt-card > .gcard__in { height: 100%; padding: clamp(26px, 3vw, 40px); display: flex; flex-direction: column; }
.fsx-ways .wt-card h3 { font-weight: 700; font-size: clamp(24px, 2.2vw, 30px); margin-bottom: 18px; }
.fsx-ways .wt-fit { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; }
.fsx-ways .wt-fit h4 { font-weight: 700; font-size: 16px; margin-bottom: 10px; }
.fsx-ways .wt-fit li { display: flex; gap: 9px; padding: 4px 0; font-size: 15.5px; line-height: 1.45; color: var(--body); }
.fsx-ways .wt-fit .icon { width: 18px; height: 18px; flex: none; margin-top: 3px; }
.fsx-ways .wt-fit .n .icon { color: #9B98B3; }
.fsx-ways .wt-incl { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 22px; }
.fsx-ways .wt-incl span { display: inline-flex; align-items: center; gap: 7px; padding: 8px 13px; border-radius: 999px; background: var(--tint); font-family: var(--font-ui); font-size: 14px; font-weight: 600; color: var(--navy); }
.fsx-ways .wt-incl .icon { width: 16px; height: 16px; }
.fsx-ways .wt-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 14px 24px; margin-top: auto; padding-top: 24px; border-top: 1px solid var(--line); }
.fsx-ways .wt-card .wt-foot { margin-top: 26px; }
.fsx-ways .wt-foot p { font-size: 17px; color: var(--body); }
.fsx-ways .wt-foot b { color: var(--navy); }
.fsx-ways .wt-diy { display: flex; flex-direction: column; gap: 16px; }
.fsx-ways .wt-diy .diy-logos { display: flex; flex-wrap: wrap; gap: 14px 34px; margin: 0; }
.fsx-ways .wt-diy .diy-logos img { height: 60px; width: auto; }
.fsx-ways .wt-diy h3 { font-weight: 700; font-size: clamp(28px, 2.8vw, 40px); line-height: 1.1; }
.fsx-ways .wt-diy > p { font-size: 17.5px; color: var(--body); }
.fsx-ways .wt-diy .vid { --bw: 5px; --r: 36px; margin-top: 6px; }
.fsx-ways .wt-list { display: grid; margin: 0; padding: 0; list-style: none; }
.fsx-ways .wt-res { display: grid; grid-template-columns: 92px minmax(0, 1fr) auto; gap: 18px; align-items: center; padding: 16px 0; border-bottom: 1px solid var(--line); }
.fsx-ways .wt-res:first-child { padding-top: 0; }
.fsx-ways .wt-img { width: 92px; height: 92px; border-radius: 20px; display: grid; place-items: center; overflow: hidden; background: var(--tint); }
.fsx-ways .wt-img img { max-width: 84%; max-height: 84%; width: auto; height: auto; object-fit: contain; }
.fsx-ways .wt-res h4 { font-weight: 700; font-size: 19px; }
.fsx-ways .wt-res p { margin: 3px 0 6px; font-size: 15px; line-height: 1.45; color: var(--body); }
.fsx-ways .wt-res .link-u { font-size: 16px; }
.fsx-ways .wt-price { align-self: start; padding: 6px 12px; border-radius: 999px; background: var(--tint); font-weight: 700; font-size: 15px; color: var(--navy); white-space: nowrap; }
.fsx-ways .wt-more { margin-top: 18px; font-size: 15px; color: var(--body); }
.fsx-ways .wt-more a { color: var(--blue-ink); font-weight: 600; }
@media (max-width: 1024px) { .fsx-ways .wt-panel { grid-template-columns: minmax(0, 1fr); } }
@media (max-width: 640px) { .fsx-ways .wt-tabs { grid-template-columns: 1fr; } }
@media (max-width: 640px) { .fsx-ways .wt-tabs button { padding: 12px 14px; } }
@media (max-width: 640px) { .fsx-ways .wt-fit { grid-template-columns: 1fr; } }
@media (max-width: 640px) { .fsx-ways .wt-res { grid-template-columns: 70px minmax(0, 1fr); } }
@media (max-width: 640px) { .fsx-ways .wt-img { width: 70px; height: 70px; } }
@media (max-width: 640px) { .fsx-ways .wt-price { grid-column: 2; justify-self: start; order: -1; } }
@media (max-width: 640px) { .fsx-ways .wt-foot .btn { width: 100%; } }
.fsx-ways .eyebrow { font-family: var(--font); font-size: clamp(16px, 1.35vw, 20px); font-weight: 600; letter-spacing: 0; color: #3299D5; }
.fsx-ways .h2 { font-weight: 700; font-size: clamp(32px, 3.6vw, 52px); line-height: 1.08; letter-spacing: -0.02em; }
.fsx-ways .lead, .fsx-ways .ways2-head .lead { font-size: clamp(17px, 1.35vw, 19px); line-height: 1.6; color: var(--ink); }
.fsx-ways .link-u { font-family: var(--font); font-style: italic; font-weight: 500; color: var(--navy); text-decoration: underline; text-decoration-color: #72CCD8; text-decoration-thickness: 2px; text-underline-offset: 7px; }
.fsx-ways .btn { font-family: var(--font); }
.fsx-ways .wt-tabs--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.fsx-ways .wt-img--ico { background: var(--grad-diag); color: var(--white); }
.fsx-ways .wt-img--ico .icon { width: 40px; height: 40px; }
.fsx-ways .wt-coach-price { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 18px; }
.fsx-ways .wt-coach-price > div { padding: 16px 18px; border-radius: 18px; background: var(--tint); }
.fsx-ways .wt-coach-price > div:last-child { background: var(--navy); color: var(--white); }
.fsx-ways .wt-coach-price b { font-weight: 800; font-size: 34px; color: var(--navy); }
.fsx-ways .wt-coach-price > div:last-child b { color: var(--white); }
.fsx-ways .wt-coach-price span { font-size: 15px; color: var(--muted); }
.fsx-ways .wt-coach-price > div:last-child span, .fsx-ways .wt-coach-price > div:last-child small { color: rgba(255, 255, 255, .8); }
.fsx-ways .wt-coach-price small { display: block; font-family: var(--font-ui); font-size: 13.5px; color: var(--body); }
.fsx-ways .wt-coach { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.fsx-ways .wt-coach li { display: flex; gap: 10px; font-size: 16px; color: var(--ink); }
.fsx-ways .wt-coach .icon { width: 19px; height: 19px; flex: none; margin-top: 3px; }
@media (max-width: 900px) { .fsx-ways .wt-tabs--3 { grid-template-columns: minmax(0, 1fr); } }
@media (max-width: 480px) { .fsx-ways .wt-coach-price { grid-template-columns: 1fr; } }
.fsx-ways .gt { color: transparent; background: var(--grad-text); -webkit-background-clip: text; background-clip: text; -webkit-box-decoration-break: clone; box-decoration-break: clone; }
.fsx-ways .ways2-head { margin-inline: auto; text-align: center; max-width: 880px; }
.fsx-ways .ways2-head .lead { margin-inline: auto; }
